-- ─────────────────────────────────────────────────────────────────────────────
-- Public (anon) access: the declaration link at /declaration/:token is filled
-- out by the individual, not a logged-in user. form_templates/form_versions
-- RLS only allows 'authenticated' to read, so a narrow SECURITY DEFINER
-- function exposes just the single fit_and_proper declaration form's schema —
-- nothing else in form_templates/form_versions is exposed to anon.
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.get_fp_declaration_form_public()
RETURNS TABLE(template_id UUID, version_id UUID, schema_snapshot JSONB)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT ft.id, fv.id, fv.schema_snapshot
  FROM public.form_templates ft
  JOIN public.form_versions fv ON fv.template_id = ft.id
  WHERE ft.form_type = 'fit_and_proper'
  ORDER BY fv.version DESC
  LIMIT 1;
$$;

GRANT EXECUTE ON FUNCTION public.get_fp_declaration_form_public() TO anon, authenticated;
